def _validate_per_message_contexts(
    contexts: Any, messages: Any, shared_context: Any
) -> tuple[bytes, ...] | None:
    """Validate the optional per-message ``contexts`` tuple for batch APIs.

    ``None`` means the legacy shared-``context`` path: the caller keeps the
    already-normalised ``shared_context`` bytes and this returns ``None``.
    Otherwise ``contexts`` must be a tuple with one member per message, each
    member normalised by :func:`_validate_context` (``None``/empty equals the
    empty context and a ``str`` is UTF-8 encoded). Per-message contexts are
    mutually exclusive with a non-empty shared ``context``.

    The checks run in a fixed order — containers and member types first, then
    the length and the shared-context conflict, so a non-tuple ``contexts``
    or a bad member type raises ``TypeError``; a length mismatch or a
    non-empty shared context raises ``ValueError``. Capacity checks are the
    caller's job and follow afterwards, inside the signing lock.
    """
    if contexts is None:
        return None
    if not isinstance(contexts, tuple):
        raise TypeError("contexts must be a tuple of contexts")
    normalised = tuple(_validate_context(item) for item in contexts)
    if len(normalised) != len(messages):
        raise ValueError("contexts and messages must have the same length")
    if _validate_context(shared_context):
        raise ValueError(
            "per-message contexts cannot be combined with a non-empty context"
        )
    return normalised

